function User({ id }) {
  if (!id) return null;
  const [user, setUser] = useState(null);
  useEffect(() => {
    fetch('/api/users/' + id).then((r) => r.json()).then(setUser);
  }, []);
  return <div>{user?.name}</div>;
}

